import six
from .singleton import ThreadSafeSingleton


class NoConstructionGeneratorRegisteredForElement(Exception):
    """No Construction Generator Registered For Element"""
    pass  # pylint: disable=unnecessary-pass


@six.add_metaclass(ThreadSafeSingleton)
class NetworkElementFactory:
    """Factory of NE."""
    def __init__(self):
        """Basic initialization."""
        self._elems_registry = {}

    def register_construction(self, element2create, network_elem_type, variant, construction_generator):
        """
        Register construction generator that will return "element construction recipe" in form of
        iterator over (class2construct_name, constructor_parameters)
        :param element2create: what element the registration is for - ex. 'message_source', 'network_element', ...
        :param network_elem_type: 'UE', 'MME', 'ENB', ...
        :param variant: implementation variant, ex. for 'UE' it might be 'wts', 'qualcomm', 'android', ...
        :param construction_generator: might be list, lambda, function, generator function, generator object
        :return: None
        """
        self._elems_registry[(element2create, network_elem_type, variant)] = construction_generator

    def construction_recipe(self, element2create, network_elem_type, variant, **construction_generator_kwargs):
        """
        Return iterator giving full info for constructing new objects - might be used by instance_loader.create_instance_from_class_fullname().
        It is calculated via previously registered construction_generator.
        It's value may depend on **construction_generator_kwargs
        :param element2create: which element we want
        :param network_elem_type: which type we want (UE/MME/ENB...)
        :param variant: which variant of that type we want
        :param construction_generator_kwargs: parameters passed to registered construction_generator (if it is callable)
        :return: iterator over pairs (class2construct_name, constructor_parameters).
        """
        requested_element_key = (element2create, network_elem_type, variant)
        if requested_element_key not in self._elems_registry:
            raise NoConstructionGeneratorRegisteredForElement(f"requested element: {requested_element_key}")
        construction_generator = self._elems_registry[requested_element_key]
        if callable(construction_generator):
            return construction_generator(**construction_generator_kwargs)
        return construction_generator

    def available_variants(self, element2create, network_elem_type):
        """
        Return variants available for given element2create & network_elem_type.

        :return: set of variants
        """
        known_variants = []
        for (element, ne_type, variant) in self._elems_registry:
            if (element == element2create) and (ne_type == network_elem_type):
                known_variants.append(variant)
        return set(known_variants)
